diff --git a/src/cart.js b/src/cart.js
index 9c7f263..c1a029b 100644
--- a/src/cart.js
+++ b/src/cart.js
@@ -47,11 +47,21 @@ export class Cart {
    */
   total() {
     const subtotal = this.subtotal()
-    const taxed = Math.round(subtotal * (1 + TAX_RATE))
     const discount = this.discountCode ? DISCOUNT_CODES[this.discountCode] : null
-    if (!discount) return taxed
-    if (discount.type === 'percent') return Math.round(taxed * (1 - discount.value / 100))
-    return Math.max(0, taxed - discount.value)
+    // No discount: tax on subtotal as before
+    if (!discount) {
+      return Math.round(subtotal * (1 + TAX_RATE))
+    }
+    // Percent discounts: keep existing behavior (apply percent after tax)
+    if (discount.type === 'percent') {
+      const taxed = Math.round(subtotal * (1 + TAX_RATE))
+      return Math.round(taxed * (1 - discount.value / 100))
+    }
+    // Fixed discount: apply discount before tax, clamp taxable base at zero,
+    // round tax to nearest cent, then total = discounted_base + tax
+    const discountedBase = Math.max(0, subtotal - discount.value)
+    const tax = Math.round(discountedBase * TAX_RATE)
+    return discountedBase + tax
   }

   /** Remove purchased quantities from the inventory and empty the cart. */
